// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        // The deployer of c is this test contract, hence c.owner() == address(this).
        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the legitimate owner can always transfer ownership,
        // and the new owner is recorded afterwards.
        assertTrue(ok && c.owner() == newOwner);
    }
}
